INSERT INTO SEB400 (  /* 서비스제공의뢰 */
    SRVC_PVSN_RQST_NO                    /* 서비스제공의뢰번호 */
    , HPE_SRVC_YN                        /* 희망서비스여부 */
    , RQST_UNT_TASKWK_SE_CD              /* 의뢰단위업무구분코드 */
    , RCPT_RQST_COURS_SE_CD              /* 접수의뢰경로구분코드 */
    , RQST_YMD                           /* 의뢰일자 */

    , CLINT_NO                           /* 의뢰자번호 */
    , RQST_INST_NO                       /* 의뢰기관번호 */
    , RQST_CS_CN                         /* 의뢰사유내용 */
    , RCPT_UNT_TASKWK_SE_CD              /* 접수단위업무구분코드 */
    , RCPT_INST_NO                       /* 접수기관번호 */

    , RQST_TRPR_INFO_NO                  /* 의뢰대상자정보번호 */
    , RQST_APLY_YN                       /* 의뢰신청여부 */
    , RQST_DTL_CN                        /* 의뢰상세내용 */
    , LINK_TYPE_SE_CD                    /* 연계유형구분코드 */
    , TRMN_PRCS_YN                       /* 종결처리여부 */

    , DEL_YN                             /* 삭제여부 */
    , FRST_RGTR_ID                           
    , FRST_REG_DT                           
    , LAST_MDFR_ID                           
    , LAST_MDFCN_DT                           
) VALUES (
    #{SRVC_PVSN_RQST_NO}
    , #{HPE_SRVC_YN}
    , #{RQST_UNT_TASKWK_SE_CD}
    , #{RCPT_RQST_COURS_SE_CD}
    , TO_CHAR(SYSDATE, 'YYYYMMDD')

    , #{CLINT_NO}
    , TO_NUMBER(#{RQST_INST_NO})
    , #{RQST_CS_CN}
    , #{RCPT_UNT_TASKWK_SE_CD}
    , #{RCPT_INST_NO}

    , #{RQST_TRPR_INFO_NO}
    , #{RQST_APLY_YN}
    , #{RQST_DTL_CN}
    , #{LINK_TYPE_SE_CD}
    , #{TRMN_PRCS_YN}

    , #{DEL_YN}

    , #{USER_ID}
    , SYSDATE
    , #{USER_ID}
    , SYSDATE
)

