    , FAM_SHAPE_SE_CD               /* 가족형태구분코드 */

    , INDV_IDNTFC_INFO_UNIPT_CS_CN  /* 개인식별정보미입력사유내용 */
    , INDV_IDNTFC_CRTR_YMD          /* 개인식별기준일자 */
    , RCPT_RQST_COURS_SE_CD         /* 접수의뢰경로구분코드 */
    , DEL_YN                        /* 삭제여부 */

    , FRST_RGTR_ID                   
