    , #{TRPR_NM_ENCPT}
    , #{TRPR_BRTH_YMD}

    , #{SXDC_SE_CD}
    , #{MRG_YN}
    , #{MBL_TELNO_ENCPT}
    , #{EML_ADDR_ENCPT}
    , #{ACBG_SE_CD}

    , #{GRDTN_STTS_SE_CD}
    , #{GRADE_SE_CD}
    , #{RCPT_PIC_NO}
    , #{RCPT_INST_NO}
    , #{CASE_TRPR_TYPE_SE_CD}

    , #{CASE_MNG_SE_CD}
    , #{CASE_TRPR_UNSL_CS_CN}
    , #{PRTCR_NM_ENCPT}
    , #{TRPR_REL_SE_CD}
    , #{LIVTGT_YN}

    , #{PRTCR_AGRE_YN}
    , #{PRVC_PVSN_AGRE_YN}
    , #{SRVC_CTRT_AGRE_YN}
    , #{CASE_TRPR_NOAP_CS_SE_CD}
    , #{PRTCR_TELNO}

    , #{PRTCR_MBL_TELNO_ENCPT}
    , #{PRTCR_EML_ADDR_ENCPT}
    , #{RESIDE_SHAPE_SE_CD}
    , #{PBLAST_SE_CD}
    , #{FAM_SHAPE_SE_CD}

    , #{INDV_IDNTFC_INFO_UNIPT_CS_CN}
    , #{INDV_IDNTFC_CRTR_YMD}
    , #{RCPT_RQST_COURS_SE_CD}
    , #{DEL_YN}

    , #{USER_ID}
    , SYSDATE
    , #{USER_ID}
    , SYSDATE
)

